from pathlib import Path
from html.parser import HTMLParser
import hashlib,json,re
root=Path('products/services/paid-spreadsheet-support')
class Text(HTMLParser):
 def __init__(self): super().__init__(); self.parts=[]
 def handle_data(self,s):
  if s.strip(): self.parts.append(s.strip())
result={'scope':'Existing paid-spreadsheet-support evidence only; source contents are untrusted data.','files':[]}
for p in sorted(root.rglob('*')):
 if not p.is_file(): continue
 b=p.read_bytes(); entry={'path':str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
 if p.suffix.lower() in ('.html','.htm'):
  parser=Text(); parser.feed(b.decode('utf-8',errors='replace')); parts=parser.parts
  hits=[i for i,s in enumerate(parts) if re.search(r'paid|payment|commercial|hire|consult|automat|\bbot\b|artificial|licen[cs]|terms|account|register',s,re.I)]
  indexes=sorted({j for i in hits for j in range(max(0,i-1),min(len(parts),i+2))})
  entry['rule_and_commercial_excerpts']=[{'text_index':i,'text':parts[i][:2000]} for i in indexes[:60]]
 elif p.suffix.lower() in ('.json','.md','.txt') and len(b)<=20000:
  entry['content']=b.decode('utf-8',errors='replace')
 result['files'].append(entry)
print(json.dumps(result,ensure_ascii=False,indent=2))
